7	import { useKeatingAgent } from "../hooks/useKeatingAgent";
8	import {
9		getLiveSpeechBridge,
10		getSpeechProvider,
11		loadWebSpeechSettings,
12		primeSpeechAudio,
13		resolveSpeechRealtimeTier,
14		speechErrorMessage,
15		type LiveSpeechSession,
16		type LiveSpeechState,
17	} from "../keating/speech";
18	import { startVideoCapture, type VideoCaptureHandle } from "../keating/video-capture";
19	import type { ConversationEvent } from "../keating/protocol";
20	import { getProviderApiKey } from "../lib/provider-models";
