22	/**
23	 * The live session surface.
24	 *
25	 * Keating's mascot is a CRT monitor with a face, so a live A/V session gets
26	 * rendered as exactly that: the learner's camera feed becomes the phosphor
27	 * screen behind the bezel, and Keating's own face takes over whenever he has
28	 * nothing to look at. Status, tools, and transcript are all terminal readouts,
29	 * matching the boot sequence and the landing hero.
30	 */
31	
32	const STATE_LABEL: Record<LiveSpeechState, string> = {
33		connecting: "connecting",
34		listening: "listening",
35		speaking: "speaking",
36		closed: "standby",
37	};
38	
39	interface ToolEntry {
40		callId: string;
41		name: string;
42		status: "running" | "completed" | "failed";
43	}
44	
45	interface TranscriptEntry {
46		role: "user" | "assistant";
47		text: string;
48	}
49	
50	/**
51	 * Keep the normal Keating agent lifecycle mounted when /live is opened
52	 * directly. Chat normally owns this hook, but the live surface still needs
53	 * its prompt, history, tools, executor, and canonical-event persistence.
54	 */
55	function StandaloneLiveAgentBridge() {
56		const { chatPanelRef } = useKeatingAgent();
57	
58		return (
59			<div aria-hidden="true" className={css({ display: "none" })}>
60				<AssistantChatPanel ref={chatPanelRef} />
61			</div>
62		);
63	}
64	
65	/**
66	 * Dotted leader between a label and its status, as in the boot sequence.
67	 *
68	 * The dots are a border rather than repeated glyphs: a run of non-breaking
69	 * characters contributes its full width to max-content sizing and will drag the
70	 * whole grid column wider than its cell.
71	 */
72	function Leader({ label, value, tone }: { label: string; value: string; tone?: "ok" | "fail" | "pending" }) {
73		return (
74			<div className={css({ display: "flex", alignItems: "baseline", gap: "0.5rem", fontSize: "0.8125rem", minWidth: 0 })}>
75				<span className={css({ minWidth: 0, overflow: "hidden", textOverflow: "ellipsis", whiteSpace: "nowrap" })}>
76					{label}
77				</span>
78				<span
79					aria-hidden="true"
80					className={css({
81						flex: "1 1 auto",
82						minWidth: "0.75rem",
83						alignSelf: "center",
84						borderBottom: "1px dotted currentColor",
85						opacity: 0.35,
86					})}
87				/>
88				<span
89					className={css({
90						whiteSpace: "nowrap",
91						flexShrink: 0,
92						color: tone === "fail"
93							? "var(--red)"
94							: tone === "pending"
95								? "var(--amber)"
96								: "var(--phosphor)",
97					})}
98				>
99					{value}
100				</span>
101			</div>
102		);
103	}
104	
105	export function Live() {
106		const settings = useMemo(() => loadWebSpeechSettings(), []);
107		const tier = useMemo(() => resolveSpeechRealtimeTier(settings), [settings]);
108	
109		const [state, setState] = useState<LiveSpeechState>("closed");
110		const [active, setActive] = useState(false);
111		const [error, setError] = useState<string | null>(null);
112		const [transcript, setTranscript] = useState<TranscriptEntry[]>([]);
113		const [tools, setTools] = useState<ToolEntry[]>([]);
114		const [framesSent, setFramesSent] = useState(0);
115		const [firstAudioMs, setFirstAudioMs] = useState<number | null>(null);
116		const [videoLive, setVideoLive] = useState(false);
117	
118		const sessionRef = useRef<LiveSpeechSession | null>(null);
119		const videoRef = useRef<VideoCaptureHandle | null>(null);
120		const abortRef = useRef<AbortController | null>(null);
121		const previewRef = useRef<HTMLVideoElement | null>(null);
122		const transcriptRef = useRef<HTMLDivElement | null>(null);
123		const startedAtRef = useRef<number>(0);
124	
125		const appendTranscript = useCallback((role: "user" | "assistant", text: string) => {
126			if (!text) return;
127			setTranscript((prev) => {
128				const last = prev[prev.length - 1];
129				// Deltas from the same speaker coalesce; a change of speaker starts a
130				// new line.
131				if (last && last.role === role) {
132					return [...prev.slice(0, -1), { role, text: last.text + text }];
133				}
134				return [...prev, { role, text }];
135			});
136		}, []);
137	
138		// Keep the newest line in view without yanking the page around.
139		useEffect(() => {
140			const node = transcriptRef.current;
141			if (node) node.scrollTop = node.scrollHeight;
142		}, [transcript]);
143	
144		const stop = useCallback(() => {
145			abortRef.current?.abort();
146			abortRef.current = null;
147			void sessionRef.current?.stop().catch(() => {});
148			sessionRef.current = null;
149			videoRef.current?.stop();
150			videoRef.current = null;
151			if (previewRef.current) previewRef.current.srcObject = null;
152			setVideoLive(false);
153			setActive(false);
154			setState("closed");
155		}, []);
156	
157		// A live session holds the microphone, the camera, and a paid socket; it
158		// must not survive the user navigating away.
159		useEffect(() => stop, [stop]);
160	
161		const onConversationEvent = useCallback((event: ConversationEvent) => {
162			switch (event.type) {
163				case "tool.requested":
164					setTools((prev) => [
165						...prev,
166						{ callId: event.payload.callId, name: event.payload.name, status: "running" },
167					]);
168					break;
169				case "tool.completed":
170				case "tool.failed":
171					setTools((prev) => prev.map((entry) =>
172						entry.callId === event.payload.callId
173							? { ...entry, status: event.type === "tool.completed" ? "completed" : "failed" }
174							: entry));
175					break;
176				default:
177					break;
178			}
179		}, []);
180	
181		const start = useCallback(async () => {
182			setError(null);
183			setTranscript([]);
184			setTools([]);
185			setFramesSent(0);
186			setFirstAudioMs(null);
187			setState("connecting");
188			setActive(true);
189			startedAtRef.current = Date.now();
190	
191			const abort = new AbortController();
192			abortRef.current = abort;
193			// Screen sharing requires transient user activation. Begin the request
194			// synchronously from the Start Session button before provider setup awaits
195			// can consume that activation; the resolved handle is used below.
196			const pendingScreenCapture = settings.videoEnabled && tier.video && settings.videoSource === "screen"
197				? startVideoCapture({
198					source: settings.videoSource,
199					intervalMs: settings.frameIntervalMs,
200				}).catch((err) => {
201					console.warn("[keating:live] screen capture unavailable", err);
202					return null;
203				})
204				: null;
205	
206			try {
207				// Browsers only unlock audio playback inside a user gesture, and this
208				// runs from the power button's handler.
209				await primeSpeechAudio();
210	
211				const provider = await getSpeechProvider(settings.providerId);
212				if (!provider?.startLiveSession) {
213					throw new Error("This speech provider cannot hold a live session. Pick OpenAI Realtime or Gemini Live in Settings → Speech.");
214				}
215	
216				let video: VideoCaptureHandle | null = null;
217				if (settings.videoEnabled && tier.video) {
218					try {
219						video = await (pendingScreenCapture ?? startVideoCapture({
220							source: settings.videoSource,
221							intervalMs: settings.frameIntervalMs,
222						}));
223						if (!video) throw new Error("Video capture was unavailable.");
224						videoRef.current = video;
225						if (previewRef.current) {
226							previewRef.current.srcObject = video.stream;
227							void previewRef.current.play().catch(() => {});
228						}
229						video.onFrame(() => setFramesSent((count) => count + 1));
230						setVideoLive(true);
231					} catch (err) {
232						// Vision is optional; a declined camera prompt must not cost the
233						// learner their voice session.
234						console.warn("[keating:live] video capture unavailable", err);
235						setError(speechErrorMessage(err, "Camera or screen capture was unavailable. Continuing with audio only."));
236					}
237				}
238	
239				const bridge = getLiveSpeechBridge();
240				const session = await provider.startLiveSession({
241					settings,
242					getApiKey: getProviderApiKey,
243					signal: abort.signal,
244					instructions: bridge?.instructions,
245					history: bridge?.history,
246					tools: bridge?.tools,
247					video,
248					onToolCall: bridge ? (call) => bridge.execute(call, abort.signal) : undefined,
249					onConversationEvent,
250					onState: (next) => {
251						setState(next);
252						if (next === "speaking") {
253							setFirstAudioMs((current) => current ?? Date.now() - startedAtRef.current);
254						}
255					},
256					onUserTranscript: (text) => appendTranscript("user", text),
257					onAssistantTranscript: (text) => appendTranscript("assistant", text),
258					onError: (err) => setError(err.message),
259				});
260				sessionRef.current = session;
261			} catch (err) {
262				setError(speechErrorMessage(err, "The live session could not be started."));
263				stop();
264			}
265		}, [appendTranscript, onConversationEvent, settings, stop, tier.video]);
266	
267		const speaking = state === "speaking";
268	
269		return (
270			<div className={cx("retro-layout", "retro-page")}>
271				<StandaloneLiveAgentBridge />
272				<Nav />
273				<main className={css({ maxWidth: "68rem", marginInline: "auto", padding: "1.5rem", display: "grid", gap: "1.5rem" })}>
274					<header className={css({ display: "grid", gap: "0.5rem" })}>
275						<div className={cx("prompt", css({ fontSize: "0.8125rem", opacity: 0.75 }))}>
276							keating --live --tier={tier.tier}
277						</div>
278						<h1 className={css({ fontFamily: "var(--mono-display)", fontSize: "1.75rem", fontWeight: 700, lineHeight: 1.2 })}>
279							{tier.label}
280						</h1>
281						{tier.capReason && (
282							<p className={css({ fontSize: "0.875rem", opacity: 0.75, maxWidth: "48rem" })}>
283								{tier.capReason}
284							</p>
285						)}
286					</header>
287	
288					{error && (
289						<div
290							role="alert"
291							className={css({
292								border: "1px solid var(--red)",
293								borderRadius: "0.375rem",
294								padding: "0.75rem 1rem",
295								fontSize: "0.875rem",
296								color: "var(--red)",
297								background: "color-mix(in srgb, var(--red) 8%, transparent)",
298							})}
299						>
300							{error}
301						</div>
302					)}
303	
304					<div className={css({ display: "grid", gap: "1.5rem", gridTemplateColumns: "minmax(0, 1fr)", lg: { gridTemplateColumns: "minmax(0, 1.15fr) minmax(0, 1fr)" } })}>
305						{/* The viewport — Keating's CRT face, showing whatever he can see. */}
306						{/* minmax(0, 1fr) so a wide child can never stretch the column. */}
307						<section className={css({ display: "grid", gridTemplateColumns: "minmax(0, 1fr)", gap: "1rem", alignContent: "start", minWidth: 0 })}>
308							<div
309								className={cx(
310									"crt",
311									"terminal-glow",
312									css({
313										position: "relative",
314										overflow: "hidden",
315										aspectRatio: "4 / 3",
316										// Never let the viewport eat a whole phone screen.
317										maxHeight: "min(56dvh, 30rem)",
318										minWidth: 0,
319										borderRadius: "0.75rem",
320										border: "3px solid var(--terminal-edge)",
321										background: "var(--terminal)",
322										// Column flow: content region above, status row below, so
323										// nothing can overlap at any viewport size.
324										display: "flex",
325										flexDirection: "column",
326										transitionProperty: "box-shadow, border-color",
327										transitionDuration: "300ms",
328									}),
329									// The bezel brightens while Keating is talking, so the
330									// speaking state is legible from across a room.
331									speaking ? css({ borderColor: "var(--phosphor)" }) : "",
332								)}
333							>
