1	/**
2	 * Provider-agnostic frame capture for live sessions.
3	 *
4	 * Both realtime providers Keating targets consume sampled JPEG frames rather
5	 * than a continuous video track — Gemini Live has a dedicated video lane capped
6	 * at 1 fps, and GPT Realtime accepts still images as conversation items. So
7	 * there is one capture pipeline here and the providers supply their own sink.
8	 *
9	 * Nothing in this module may import provider types.
10	 */
11	
12	/** Both providers cap video at one frame per second. */
13	export const MIN_FRAME_INTERVAL_MS = 1000;
14	export const DEFAULT_MAX_EDGE = 768;
15	export const DEFAULT_JPEG_QUALITY = 0.6;
16	/**
17	 * Histogram distance below which a frame is considered a repeat of the previous
18	 * one and skipped. Tuned to drop a static desk/screen while still catching a
19	 * page scroll or a hand entering frame.
20	 */
21	export const DEFAULT_SIMILARITY_THRESHOLD = 0.02;
22	
23	const HISTOGRAM_BINS = 32;
24	
25	export type VideoSource = "camera" | "screen";
26	
27	export interface VideoCaptureOptions {
28		source?: VideoSource;
29		/** Milliseconds between sampled frames. Floored to MIN_FRAME_INTERVAL_MS. */
30		intervalMs?: number;
31		/** Longest edge of the encoded frame, in pixels. */
32		maxEdge?: number;
33		jpegQuality?: number;
34		/** Set to 0 to emit every frame regardless of similarity. */
35		similarityThreshold?: number;
36	}
37	
38	export interface NormalizedCaptureOptions {
39		source: VideoSource;
40		intervalMs: number;
41		maxEdge: number;
42		jpegQuality: number;
43		similarityThreshold: number;
44	}
45	
46	export interface CapturedFrame {
47		/** Base64 JPEG payload, no data-URL prefix. */
48		data: string;
49		/** Full data URL, which is what the OpenAI image content part wants. */
50		dataUrl: string;
51		mimeType: "image/jpeg";
52		width: number;
53		height: number;
54		capturedAt: number;
55	}
56	
57	export type FrameListener = (frame: CapturedFrame) => void;
58	
59	export interface VideoCaptureHandle {
60		/** Live stream, for rendering a local preview. */
61		readonly stream: MediaStream;
62		readonly source: VideoSource;
63		/** Frames emitted so far, including on-demand captures. */
64		readonly frameCount: number;
65		/** Subscribe to the sampled frame feed. Returns an unsubscribe function. */
66		onFrame(listener: FrameListener): () => void;
67		/** Grab a frame immediately, bypassing the interval and similarity skip. */
68		captureFrameNow(): Promise<CapturedFrame | null>;
69		stop(): void;
70	}
71	
72	export function normalizeCaptureOptions(options: VideoCaptureOptions = {}): NormalizedCaptureOptions {
73		return {
74			source: options.source === "screen" ? "screen" : "camera",
75			intervalMs: Math.max(MIN_FRAME_INTERVAL_MS, Math.floor(options.intervalMs ?? MIN_FRAME_INTERVAL_MS)),
76			maxEdge: Math.max(64, Math.floor(options.maxEdge ?? DEFAULT_MAX_EDGE)),
77			jpegQuality: Math.min(1, Math.max(0.1, options.jpegQuality ?? DEFAULT_JPEG_QUALITY)),
78			similarityThreshold: Math.max(0, options.similarityThreshold ?? DEFAULT_SIMILARITY_THRESHOLD),
79		};
80	}
81	
82	/**
83	 * Scale a frame so its longest edge is at most maxEdge, preserving aspect
84	 * ratio. Frames already within budget are left alone — upscaling would only
85	 * cost tokens without adding detail.
86	 */
87	export function computeCaptureSize(
88		width: number,
89		height: number,
90		maxEdge: number,
91	): { width: number; height: number } {
92		if (width <= 0 || height <= 0) return { width: 0, height: 0 };
93		const longest = Math.max(width, height);
94		if (longest <= maxEdge) return { width: Math.round(width), height: Math.round(height) };
95		const scale = maxEdge / longest;
96		return {
97			width: Math.max(1, Math.round(width * scale)),
98			height: Math.max(1, Math.round(height * scale)),
99		};
100	}
101	
102	/**
103	 * Normalized luma histogram over RGBA pixel data. Cheap enough to run on every
104	 * candidate frame and stable against sensor noise, which a per-pixel diff is
105	 * not.
106	 */
107	export function lumaHistogram(pixels: ArrayLike<number>, bins = HISTOGRAM_BINS): Float64Array {
108		const histogram = new Float64Array(bins);
109		const pixelCount = Math.floor(pixels.length / 4);
110		if (pixelCount === 0) return histogram;
111		for (let i = 0; i < pixelCount; i += 1) {
112			const offset = i * 4;
113			// Rec. 601 luma; the exact weights matter less than being consistent.
114			const luma = 0.299 * pixels[offset] + 0.587 * pixels[offset + 1] + 0.114 * pixels[offset + 2];
115			const bin = Math.min(bins - 1, Math.floor((luma / 256) * bins));
116			histogram[bin] += 1;
117		}
118		for (let i = 0; i < bins; i += 1) histogram[i] /= pixelCount;
119		return histogram;
120	}
121	
122	/** Total variation distance between two normalized histograms, in [0, 1]. */
123	export function histogramDistance(a: ArrayLike<number>, b: ArrayLike<number>): number {
124		if (a.length !== b.length) return 1;
125		let sum = 0;
126		for (let i = 0; i < a.length; i += 1) sum += Math.abs(a[i] - b[i]);
127		return sum / 2;
128	}
129	
130	export function framesAreSimilar(
131		previous: ArrayLike<number> | null,
132		next: ArrayLike<number>,
133		threshold: number,
134	): boolean {
135		if (previous === null || threshold <= 0) return false;
136		return histogramDistance(previous, next) < threshold;
137	}
138	
139	/**
140	 * True when a frame should not be sent: the document is hidden, or the frame is
141	 * indistinguishable from the last one we sent. Extracted so the policy is
142	 * testable without a camera.
143	 */
144	export function shouldSkipFrame(input: {
145		documentHidden: boolean;
146		previousHistogram: ArrayLike<number> | null;
147		nextHistogram: ArrayLike<number>;
148		similarityThreshold: number;
149	}): boolean {
150		if (input.documentHidden) return true;
151		return framesAreSimilar(input.previousHistogram, input.nextHistogram, input.similarityThreshold);
152	}
153	
154	async function requestStream(source: VideoSource): Promise<MediaStream> {
155		if (typeof navigator === "undefined" || !navigator.mediaDevices) {
156			throw new Error("Video capture is unavailable in this environment.");
157		}
158		if (source === "screen") {
159			if (!navigator.mediaDevices.getDisplayMedia) {
160				throw new Error("Screen sharing is not supported by this browser.");
161			}
162			return await navigator.mediaDevices.getDisplayMedia({ video: true, audio: false });
163		}
164		if (!navigator.mediaDevices.getUserMedia) {
165			throw new Error("Camera capture is not supported by this browser.");
166		}
167		return await navigator.mediaDevices.getUserMedia({
168			video: { width: { ideal: 1280 }, height: { ideal: 720 } },
169			audio: false,
170		});
171	}
172	
173	/**
174	 * Begin sampling frames from the camera or screen. The returned handle is inert
175	 * until something subscribes via onFrame; the timer runs regardless so that
176	 * captureFrameNow always has a warm video element.
177	 */
178	export async function startVideoCapture(options: VideoCaptureOptions = {}): Promise<VideoCaptureHandle> {
179		const config = normalizeCaptureOptions(options);
180		const stream = await requestStream(config.source);
181	
182		const video = document.createElement("video");
183		video.autoplay = true;
184		video.muted = true;
185		video.playsInline = true;
186		video.srcObject = stream;
187	
188		const canvas = document.createElement("canvas");
189		const context = canvas.getContext("2d", { willReadFrequently: true });
190	
191		const listeners = new Set<FrameListener>();
192		let previousHistogram: Float64Array | null = null;
193		let frameCount = 0;
194		let stopped = false;
195		let timer: ReturnType<typeof setInterval> | null = null;
196	
197		await video.play().catch(() => {
198			// Autoplay of a muted local stream is permitted; a rejection here means
199			// the track ended before playback started, which stop() will clean up.
200		});
201	
202		const grab = (options: { force: boolean }): CapturedFrame | null => {
203			if (stopped || !context) return null;
204			const width = video.videoWidth;
205			const height = video.videoHeight;
206			if (width === 0 || height === 0) return null;
207	
208			const size = computeCaptureSize(width, height, config.maxEdge);
209			canvas.width = size.width;
210			canvas.height = size.height;
211			context.drawImage(video, 0, 0, size.width, size.height);
212	
213			const histogram = lumaHistogram(context.getImageData(0, 0, size.width, size.height).data);
214			if (!options.force) {
215				const skip = shouldSkipFrame({
216					documentHidden: typeof document !== "undefined" && document.hidden,
217					previousHistogram,
218					nextHistogram: histogram,
219					similarityThreshold: config.similarityThreshold,
220				});
221				if (skip) return null;
222			}
223			previousHistogram = histogram;
224	
225			const dataUrl = canvas.toDataURL("image/jpeg", config.jpegQuality);
226			frameCount += 1;
227			return {
228				data: dataUrl.slice(dataUrl.indexOf(",") + 1),
229				dataUrl,
230				mimeType: "image/jpeg",
231				width: size.width,
232				height: size.height,
233				capturedAt: Date.now(),
234			};
235		};
236	
237		const emit = (frame: CapturedFrame | null) => {
238			if (!frame) return;
239			for (const listener of listeners) {
240				try {
241					listener(frame);
242				} catch (error) {
243					console.warn("[keating:video] frame listener failed", error);
244				}
245			}
246		};
247	
248		timer = setInterval(() => {
249			if (listeners.size === 0) return;
250			emit(grab({ force: false }));
251		}, config.intervalMs);
252	
253		const stop = () => {
254			if (stopped) return;
255			stopped = true;
256			if (timer !== null) clearInterval(timer);
257			timer = null;
258			listeners.clear();
259			stream.getTracks().forEach((track) => track.stop());
260			video.srcObject = null;
261			try {
262				video.remove();
263			} catch {}
264		};
265	
266		// A screen share ends when the user clicks the browser's "stop sharing"
267		// chrome, which surfaces only as a track ending.
268		stream.getVideoTracks().forEach((track) => track.addEventListener("ended", stop, { once: true }));
269	
270		return {
271			stream,
272			source: config.source,
273			get frameCount() {
274				return frameCount;
275			},
276			onFrame(listener) {
277				listeners.add(listener);
278				return () => listeners.delete(listener);
279			},
280			async captureFrameNow() {
281				const frame = grab({ force: true });
282				emit(frame);
283				return frame;
284			},
285			stop,
286		};
287	}
