300	export async function scheduleAudioBlob(blob: Blob): Promise<boolean> {
301		const context = getAudioContext();
302		if (!context) return false;
303		const arrayBuffer = await blob.arrayBuffer();
304		const audioBuffer = await context.decodeAudioData(arrayBuffer.slice(0));
305		const source = context.createBufferSource();
306		source.buffer = audioBuffer;
307		source.connect(context.destination);
308		const startAt = Math.max(context.currentTime + 0.03, scheduledUntil);
309		source.start(startAt);
310		scheduledUntil = startAt + audioBuffer.duration;
311		trackScheduledSource(source);
312		return true;
313	}
