464	export function createSpeechTool(
465		settings: WebSpeechSettings,
466		getApiKey: (provider: string) => Promise<string | undefined>,
467	): AgentTool {
468		return {
469			name: KEATING_VOICE_TOOL_NAME,
470			label: "Keating Voice",
471			description:
472				"Speak one short learner-facing utterance through the active speech provider (Gemini Live, OpenAI TTS, OpenAI Realtime, Supertonic-3, or a user-defined custom provider). Use for brief questions, recaps, redirects, and encouragement only.",
473			parameters: {
474				type: "object",
475				properties: {
476					text: { type: "string", description: "The exact learner-facing sentence or short paragraph to speak." },
477					tags: {
478						type: "array",
479						items: { type: "string", enum: Array.from(VOICE_TAGS) },
480						description: "Voice tags such as question, explain, verify, redirect, encourage, pause, or recap.",
481					},
482					voice: { type: "string", description: "Optional voice name. Defaults to the configured voice." },
483					pace: { type: "string", description: "Optional pacing hint." },
484					affect: { type: "string", description: "Optional affect hint." },
485				},
486				required: ["text"],
487				additionalProperties: false,
488			},
489			execute: async (_toolCallId: string, params: Record<string, unknown>, signal?: AbortSignal) => {
490				const utterance = normalizeVoiceUtterance(params, settings);
491				const line = voiceTagLine(utterance);
492				const customModel = resolveCustomModel(settings);
493	
494				let provider: SpeechProvider | null;
495				if (customModel) {
496					const mod = await import("./speech-providers/custom-tts");
497					provider = mod.customTtsProvider;
498				} else {
499					provider = await getSpeechProvider(settings.providerId);
500				}
501	
502				if (!provider) {
503					return {
504						content: [{
505							type: "text",
506							text: `${line}\n\nSpeech is enabled but no provider matched "${settings.providerId}". Open Settings → Speech to pick one.`,
507						}],
508						details: {
509							provider: settings.providerId,
510							status: "missing-provider",
511							utterance,
512						},
513					};
514				}
515	
516				try {
517					const result = await provider.synthesize({
518						utterance,
519						settings,
520						customModel,
521						getApiKey,
522						signal,
523					});
524					return {
525						content: [{
526							type: "text",
527							text: `${line}\n\nSpeech played with ${provider.label}${result.warning ? ` (${result.warning})` : ""}. Audio chunks: ${result.audioChunks}.`,
528						}],
529						details: {
530							provider: provider.id,
531							label: provider.label,
532							kind: provider.kind,
533							model: settings.model,
534							voiceName: utterance.voice,
535							utterance,
536							transcript: result.transcript,
537							audioChunks: result.audioChunks,
538							playedChunks: result.playedChunks,
539							warning: result.warning,
540						},
541					};
542				} catch (error) {
543					const message = speechErrorMessage(error, `${provider.label} speech failed.`);
544					console.warn(`[keating:speech] ${provider.id}/${settings.model} failed: ${message}`);
545					return {
546						content: [{
547							type: "text",
548							text: `${line}\n\n${provider.label} voice layer failed: ${message}\nThe main chat response can continue without speech audio.`,
549						}],
550						details: {
551							provider: provider.id,
552							label: provider.label,
553							model: settings.model,
554							voiceName: utterance.voice,
555							utterance,
556							status: "speech-error",
557							error: message,
558						},
559					};
560				}
561			},
562		} as unknown as AgentTool;
563	}
