215	function matches(value: string, matcher: string | RegExp | undefined): boolean {
216		if (matcher === undefined) return true;
217		return typeof matcher === "string" ? value === matcher : matcher.test(value);
218	}
219	
220	export function resolveProviderCapabilities(
221		model: ProviderModelDescriptor,
222		rules: readonly CapabilityRule[] = PROVIDER_CAPABILITY_RULES,
223	): { ruleId: string; capabilities: ProviderCapabilities } {
224		const rule = rules.find((candidate) =>
225			matches(model.provider, candidate.provider)
226			&& matches(model.id, candidate.model)
227			&& matches(model.api ?? "", candidate.api)
228		) ?? PROVIDER_CAPABILITY_RULES[PROVIDER_CAPABILITY_RULES.length - 1]!;
229		return { ruleId: rule.id, capabilities: rule.capabilities };
230	}
231	
232	function route(requested: boolean | undefined, support: CapabilitySupport, allowAdapters: boolean): NegotiatedRoute {
233		if (!requested) return "not-requested";
234		if (support === "native") return "native";
235		if (support === "adapter" && allowAdapters) return "adapter";
236		return "unavailable";
237	}
238	
239	export function negotiateProviderCapabilities(
240		model: ProviderModelDescriptor,
241		request: CapabilityRequest,
242		rules: readonly CapabilityRule[] = PROVIDER_CAPABILITY_RULES,
243	): CapabilityNegotiation {
244		const resolved = resolveProviderCapabilities(model, rules);
245		const capabilities = resolved.capabilities;
246		const allowAdapters = request.allowAdapters !== false;
247		const realtimeAudio = route(request.realtimeAudio, capabilities.realtimeAudio, allowAdapters);
248		const realtimeVideo = route(request.realtimeVideo, capabilities.realtimeVideo, allowAdapters);
249		const realtimeImage = route(request.realtimeImage, capabilities.realtimeImage, allowAdapters);
250		const webSearch = route(request.webSearch, capabilities.webSearch, allowAdapters);
251		const toolCalls = route(request.toolCalls, capabilities.toolCalls, allowAdapters);
252		const citations = route(request.citations, capabilities.citations, allowAdapters);
253	
254		let transport: RealtimeTransport | undefined;
255		if (realtimeAudio !== "unavailable" && realtimeAudio !== "not-requested") {
256			const preferences = request.preferredTransports ?? ["webrtc", "websocket", "livekit"];
257			transport = preferences.find((candidate) => capabilities.realtimeTransports.includes(candidate));
258		}
259	
260		const missing: CapabilityNegotiation["missing"] = [];
261		if (realtimeAudio === "unavailable") missing.push("realtimeAudio");
262		if (request.realtimeAudio && realtimeAudio !== "unavailable" && !transport) missing.push("transport");
263		if (realtimeVideo === "unavailable") missing.push("realtimeVideo");
264		if (realtimeImage === "unavailable") missing.push("realtimeImage");
265		if (webSearch === "unavailable") missing.push("webSearch");
266		if (toolCalls === "unavailable") missing.push("toolCalls");
267		if (citations === "unavailable") missing.push("citations");
268	
269		return {
270			ruleId: resolved.ruleId,
271			model,
272			capabilities,
273			realtimeAudio,
274			realtimeVideo,
275			realtimeImage,
276			transport,
277			webSearch,
278			searchTool: webSearch === "not-requested" || webSearch === "unavailable" ? undefined : capabilities.searchTool,
279			toolCalls,
280			citations,
281			missing,
282			usesFallback: [realtimeAudio, realtimeVideo, realtimeImage, webSearch, toolCalls, citations].includes("adapter"),
283		};
284	}
