286	/**
287	 * Realtime capability tiers. Keating drives every provider at the highest tier
288	 * it actually supports and degrades explicitly rather than failing:
289	 *
290	 *   3 — audio duplex + a native provider video lane + tools
291	 *   2 — audio duplex + tools, vision supplied by Keating's frame sampler
292	 *   1 — audio duplex + tools, no vision at all
293	 *   0 — no duplex session; push-to-talk STT plus one-shot TTS
294	 */
295	export type RealtimeTier = 0 | 1 | 2 | 3;
296	
297	export interface RealtimeTierDescriptor {
298		tier: RealtimeTier;
299		label: string;
300		/** True when the session can show the model what the learner sees. */
301		video: boolean;
302		/** How frames reach the model, when they can at all. */
303		videoRoute: "native" | "sampled" | "none";
304		/**
305		 * Why the tier is not higher, for surfacing in the UI. Undefined at tier 3.
306		 */
307		capReason?: string;
308	}
309	
310	const TIER_LABELS: Record<RealtimeTier, string> = {
311		3: "Audio + video duplex",
312		2: "Audio duplex + sampled vision",
313		1: "Audio duplex",
314		0: "Half duplex (push to talk)",
315	};
316	
317	/**
318	 * Collapse a model's capabilities into the tier Keating can actually drive.
319	 * Tool calling is required above tier 0: a live session that cannot reach the
320	 * Keating tool catalog is not a teaching session, so it is treated as
321	 * half-duplex regardless of how good its audio is.
322	 */
323	export function resolveRealtimeTier(
324		model: ProviderModelDescriptor,
325		rules: readonly CapabilityRule[] = PROVIDER_CAPABILITY_RULES,
326	): RealtimeTierDescriptor {
327		const { capabilities } = resolveProviderCapabilities(model, rules);
328		const hasTransport = capabilities.realtimeTransports.length > 0;
329	
330		if (capabilities.realtimeAudio !== "native" || !hasTransport) {
331			return {
332				tier: 0,
333				label: TIER_LABELS[0],
334				video: false,
335				videoRoute: "none",
336				capReason: hasTransport
337					? "This model has no native realtime audio."
338					: "This model has no realtime transport.",
339			};
340		}
341		if (capabilities.toolCalls !== "native") {
342			return {
343				tier: 0,
344				label: TIER_LABELS[0],
345				video: false,
346				videoRoute: "none",
347				capReason: "This model cannot call tools in a live session.",
348			};
349		}
350		if (capabilities.realtimeVideo === "native") {
351			return { tier: 3, label: TIER_LABELS[3], video: true, videoRoute: "native" };
352		}
353		if (capabilities.realtimeVideo === "adapter" || capabilities.realtimeImage === "native") {
354			return {
355				tier: 2,
356				label: TIER_LABELS[2],
357				video: true,
358				videoRoute: "sampled",
359				capReason: "This model has no live video lane, so Keating samples frames as still images.",
360			};
361		}
362		return {
363			tier: 1,
364			label: TIER_LABELS[1],
365			video: false,
366			videoRoute: "none",
367			capReason: "This model cannot accept image or video input.",
368		};
369	}
