			<span
				className={css({
					whiteSpace: "nowrap",
					flexShrink: 0,
					color: tone === "fail"
						? "var(--red)"
						: tone === "pending"
							? "var(--amber)"
							: "var(--phosphor)",
				})}
			>
				{value}
			</span>
		</div>
	);
}

